// Scala's prefetch answer: a contiguous primitive array, not boxed.
val xs: Array[Double] = new Array[Double](n)   // primitive array: contiguous, streams
// Array[java.lang.Double] or List[Double] boxes each element: a pointer chase.

// a Vector of a primitive case class is stored in a primitive array internally:
case class P(x: Double, y: Double, z: Double)
val ps: Vector[P] = Vector.tabulate(n)(i => P(i, i, i))   // contiguous primitive storage
